def ideas() -> list[dict[str, str]]:
    fmts = ["pov", "brain-like", "nobody-me", "expectation", "brain-vs-me", "storytime"]
    return [{"format": fmts[i % len(fmts)], "title": t[:70],
             "idea": f"{m[0].upper() + m[1:]}. The psychology: {p}. The kind fix: {f}."}
            for i, (t, m, p, f) in enumerate(_RAW)]


